function specialGrid(n) {
  // Grow the grid bottom-up: each step puts four shifted copies of the previous special grid side by side.
  let grid = [[0]];
  for (let level = 1; level <= n; level++) {
    const side = grid.length;
    const count = side * side;
    const bigger = [];
    for (let r = 0; r < 2 * side; r++) {
      const row = [];
      for (let c = 0; c < 2 * side; c++) {
        // Shift by quadrant: top-right 0, bottom-right 1, bottom-left 2, top-left 3 copies of count.
        const shift = r < side ? (c < side ? 3 : 0) : (c < side ? 2 : 1);
        row.push(grid[r % side][c % side] + shift * count);
      }
      bigger.push(row);
    }
    grid = bigger;
  }
  return grid;
}

